30	// MQTT QoS 选型：state 高频走 0，链路状态与指令通道走 1（Spec §4.1 典型约定）
31	constexpr int kQosState = 0;
32	constexpr int kQosConnection = 1;
33	constexpr int kQosOrder = 1;
34	constexpr int kQosInstantActions = 1;
