41	// 与 core 序列化器一致的 ISO 8601 UTC 时间戳，例如 2026-10-20T12:00:00.000Z
42	std::string CurrentIsoTimestampUtc() {
43	  const auto now = std::chrono::system_clock::now();
44	  const auto millis =
45	      std::chrono::duration_cast<std::chrono::milliseconds>(now.time_since_epoch()) % 1000;
46	  const std::time_t timer = std::chrono::system_clock::to_time_t(now);
47	  std::tm tm_buf{};
48	  gmtime_r(&timer, &tm_buf);
49	  std::ostringstream ss;
50	  ss << std::put_time(&tm_buf, "%Y-%m-%dT%H:%M:%S") << '.' << std::setfill('0') << std::setw(3)
51	     << millis.count() << 'Z';
52	  return ss.str();
53	}
54	
55	std::string EscapeJsonString(const std::string& input) {
56	  std::string out;
57	  out.reserve(input.size() + 8);
58	  for (const char c : input) {
59	    if (c == '"') {
60	      out += "\\\"";
61	    } else if (c == '\\') {
62	      out += "\\\\";
63	    } else {
64	      out += c;
65	    }
66	  }
67	  return out;
68	}
69	
70	std::string Trim(const std::string& s) {
71	  const auto not_space = [](unsigned char c) { return !std::isspace(c); };
72	  auto begin = std::find_if(s.begin(), s.end(), not_space);
73	  auto end = std::find_if(s.rbegin(), s.rend(), not_space).base();
74	  if (begin >= end) return {};
75	  return std::string(begin, end);
76	}
77	
78	// 简单指令 -> VDA 5050 instantActions actionType 别名表
79	struct InstantActionAlias {
80	  const char* alias;
81	  const char* action_type;
82	};
83	constexpr InstantActionAlias kInstantActionAliases[] = {
84	    {"cancelOrder", "cancelOrder"}, {"cancel", "cancelOrder"}, {"pause", "pause"},
85	    {"resume", "resume"},            {"stopPause", "stopPause"},
86	};
87	
88	}  // namespace
89	
90	// ============================================================
91	// MqttClientWrapper：Eclipse Paho MQTT C++ 的最小封装。
92	// MQTT 类型与线程完全隔离在本 TU，ROS 层只见 topic/string。
93	//
94	// 线程安全设计（防死锁）：Paho 的 receiveThread 既处理 SUBACK 等 token 应答，
95	// 也派发消息回调。因此消息回调绝不能阻塞在任何被跨阻塞调用持有的锁上，
96	// 否则会出现「回调等锁 <-> wait() 等 SUBACK」死锁。故：
97	// - handler_mutex_ 只在拷贝/清空 handler_ 的瞬间持有（微秒级）；
98	// - client_ 只被执行器线程访问（Connect/Publish/Disconnect 均在执行器线程），无需加锁；
99	// - Disconnect 先清空 handler（回调变 no-op），再用 in_flight 计数器 + 条件变量
100	//   等待在途回调退出，最后销毁 client（防止析构期回调触碰已释放的节点成员）。
101	// ============================================================
102	class MqttClientWrapper {
103	 public:
104	  using MessageHandler = std::function<void(const std::string& topic, const std::string& payload)>;
105	
106	  ~MqttClientWrapper() { Disconnect(); }
107	
108	  MqttClientWrapper() = default;
109	  MqttClientWrapper(const MqttClientWrapper&) = delete;
110	  MqttClientWrapper& operator=(const MqttClientWrapper&) = delete;
111	
112	  /// 建立连接并订阅主题。成功后启用 automatic_reconnect 自动重连；
113	  /// 失败返回 false 并销毁半成品客户端（由调用方定时重试重建）。
114	  bool Connect(const std::string& broker_uri, const std::string& client_id,
115	               const std::vector<std::string>& sub_filters, int sub_qos,
116	               const std::string& lwt_topic, const std::string& lwt_payload, int lwt_qos,
117	               MessageHandler handler, std::string* error) {
118	    {
119	      std::lock_guard<std::mutex> lock(handler_mutex_);
120	      handler_ = std::move(handler);
121	    }
122	    QuiesceCallbacks();  // 等待旧 client 的在途回调退出后再销毁
123	    DestroyClient();
124	    try {
125	      client_ = std::make_unique<mqtt::async_client>(broker_uri, client_id);
126	      client_->set_message_callback([this](mqtt::const_message_ptr msg) {
127	        in_flight_.fetch_add(1, std::memory_order_acq_rel);
128	        MessageHandler handler;
129	        {
130	          std::lock_guard<std::mutex> lock(handler_mutex_);
131	          handler = handler_;
132	        }
133	        if (handler && msg) {
134	          handler(msg->get_topic(), msg->to_string());
135	        }
136	        if (in_flight_.fetch_sub(1, std::memory_order_acq_rel) == 1) {
137	          std::lock_guard<std::mutex> lock(done_mutex_);
138	          done_cv_.notify_all();
139	        }
140	      });
141	      mqtt::connect_options_builder builder;
142	      builder.clean_session(true)
143	          .automatic_reconnect(std::chrono::seconds(1), std::chrono::seconds(60))
144	          .connect_timeout(std::chrono::seconds(5))
145	          .keep_alive_interval(std::chrono::seconds(15))
146	          .will(mqtt::will_options(lwt_topic, lwt_payload, lwt_qos, true /*retained*/));
147	      if (!client_->connect(builder.finalize())->wait_for(std::chrono::seconds(10))) {
148	        if (error != nullptr) *error = "连接超时";
149	        DestroyClient();
150	        return false;
151	      }
152	      for (const auto& filter : sub_filters) {
153	        if (!client_->subscribe(filter, sub_qos)->wait_for(std::chrono::seconds(5))) {
154	          if (error != nullptr) *error = "订阅超时: " + filter;
155	          DestroyClient();
156	          return false;
157	        }
158	      }
159	      connected_once_.store(true);
160	      return true;
161	    } catch (const std::exception& e) {
162	      if (error != nullptr) *error = e.what();
163	      DestroyClient();
164	      return false;
165	    }
166	  }
167	
168	  /// 发布消息。未连接时快速失败（返回 false），绝不阻塞执行器线程。
169	  /// 仅允许在执行器线程调用（与 Connect/Disconnect 串行）。
170	  bool Publish(const std::string& topic, const std::string& payload, int qos, bool retained,
171	               std::string* error) {
172	    if (client_ == nullptr) {
173	      if (error != nullptr) *error = "MQTT 客户端未初始化";
174	      return false;
175	    }
176	    if (!client_->is_connected()) {
177	      if (error != nullptr) *error = "MQTT 未连接";
178	      return false;
179	    }
180	    try {
181	      client_->publish(mqtt::make_message(topic, payload.data(), payload.size(), qos, retained));
182	      return true;
183	    } catch (const std::exception& e) {
184	      if (error != nullptr) *error = e.what();
185	      return false;
186	    }
187	  }
188	
189	  bool HasConnectedOnce() const { return connected_once_.load(); }
190	
191	  /// 优雅断连：不触发 LWT 遗嘱（正常下线不应广播 CONNECTIONBROKEN）。
192	  void Disconnect() {
193	    {
194	      std::lock_guard<std::mutex> lock(handler_mutex_);
195	      handler_ = nullptr;  // 回调屏障：此后的回调拷贝到空 handler 直接 no-op
196	    }
197	    QuiesceCallbacks();
198	    DestroyClient();
199	  }
200	
201	 private:
202	  /// 等待在途消息回调退出（带 1s 上限，防御异常路径挂死）。
203	  void QuiesceCallbacks() {
204	    std::unique_lock<std::mutex> lock(done_mutex_);
205	    done_cv_.wait_for(lock, std::chrono::seconds(1),
206	                      [this] { return in_flight_.load(std::memory_order_acquire) == 0; });
207	  }
208	
209	  /// 仅允许执行器线程调用；调用前须确保无在途回调（见 QuiesceCallbacks）。
210	  void DestroyClient() {
211	    if (client_ == nullptr) return;
212	    try {
213	      if (client_->is_connected()) {
214	        client_->disconnect()->wait_for(std::chrono::seconds(2));
215	      }
216	    } catch (...) {
217	      // 异常路径：连接可能已断，忽略即可
218	    }
219	    client_.reset();
220	  }
221	
222	  // 只保护 handler_ 的拷贝/清空，绝不在阻塞 MQTT 调用期间持有
223	  std::mutex handler_mutex_;
224	  MessageHandler handler_;
225	  std::unique_ptr<mqtt::async_client> client_;
226	
227	  // 在途回调计数（回调线程 <-> Disconnect 屏障）
228	  std::atomic<int> in_flight_{0};
229	  std::mutex done_mutex_;
230	  std::condition_variable done_cv_;
231	
232	  std::atomic<bool> connected_once_{false};
233	};
