238	Vda5050GatewayNode::Vda5050GatewayNode(const rclcpp::NodeOptions& options)
239	    : rclcpp::Node("vda5050_gateway_node", options) {
240	  declare_parameter("use_vda5050", false);
241	  declare_parameter("mqtt_broker_host", "127.0.0.1");
242	  declare_parameter("mqtt_port", 1883);
243	  declare_parameter("manufacturer", "RobotManufacturer");
244	  declare_parameter("serial_number", "default");
245	  declare_parameter("protocol_version", "v2");
246	  declare_parameter("heartbeat_ms", 5000);
247	
248	  use_vda5050_ = get_parameter("use_vda5050").as_bool();
249	  mqtt_broker_host_ = get_parameter("mqtt_broker_host").as_string();
250	  mqtt_port_ = static_cast<int>(get_parameter("mqtt_port").as_int());
251	  manufacturer_ = get_parameter("manufacturer").as_string();
252	  serial_number_ = get_parameter("serial_number").as_string();
253	  protocol_version_ = get_parameter("protocol_version").as_string();
254	  heartbeat_ms_ = static_cast<int>(get_parameter("heartbeat_ms").as_int());
255	
256	  if (!use_vda5050_) {
257	    RCLCPP_INFO(get_logger(), "VDA 5050 网关未启用 (use_vda5050=false)，节点保持空转 no-op");
258	    return;
259	  }
260	
261	  if (protocol_version_ != "v2" && protocol_version_ != "v3") {
262	    RCLCPP_WARN(get_logger(), "未知 protocol_version '%s'，按 v2 处理", protocol_version_.c_str());
263	    protocol_version_ = "v2";
264	  }
265	  if (mqtt_port_ <= 0 || mqtt_port_ > 65535) {
266	    RCLCPP_WARN(get_logger(), "非法 mqtt_port=%d，回退 1883", mqtt_port_);
267	    mqtt_port_ = 1883;
268	  }
269	  if (manufacturer_.empty()) {
270	    RCLCPP_WARN(get_logger(), "manufacturer 为空，回退 RobotManufacturer");
271	    manufacturer_ = "RobotManufacturer";
272	  }
273	  if (serial_number_.empty()) {
274	    RCLCPP_WARN(get_logger(), "serial_number 为空，回退 default");
275	    serial_number_ = "default";
276	  }
277	  if (heartbeat_ms_ <= 0) {
278	    RCLCPP_WARN(get_logger(), "非法 heartbeat_ms=%d，回退 5000", heartbeat_ms_);
279	    heartbeat_ms_ = 5000;
280	  }
281	
282	  RCLCPP_INFO(get_logger(),
283	              "VDA 5050 网关启用: broker=%s:%d base=%s gateway_identity=%s/%s heartbeat=%dms",
284	              mqtt_broker_host_.c_str(), mqtt_port_, TopicBase().c_str(), manufacturer_.c_str(),
285	              serial_number_.c_str(), heartbeat_ms_);
286	
287	  try {
288	    mqtt_ = std::make_unique<MqttClientWrapper>();
289	    drain_timer_ = create_wall_timer(std::chrono::milliseconds(kDrainPeriodMs),
290	                                     std::bind(&Vda5050GatewayNode::DrainInboundQueue, this));
291	    heartbeat_timer_ = create_wall_timer(
292	        std::chrono::milliseconds(heartbeat_ms_),
293	        std::bind(&Vda5050GatewayNode::PublishGatewayHeartbeat, this));
294	    mqtt_retry_timer_ = create_wall_timer(
295	        std::chrono::milliseconds(kMqttRetryPeriodMs),
296	        std::bind(&Vda5050GatewayNode::TryConnectMqtt, this));
297	    TryConnectMqtt();
298	  } catch (const std::exception& e) {
299	    RCLCPP_ERROR(get_logger(), "MQTT 子系统初始化失败，网关降级为空转: %s", e.what());
300	    if (drain_timer_) drain_timer_->cancel();
301	    if (heartbeat_timer_) heartbeat_timer_->cancel();
302	    if (mqtt_retry_timer_) mqtt_retry_timer_->cancel();
303	    mqtt_.reset();
304	  }
305	}
