315	void Vda5050GatewayNode::TryConnectMqtt() {
316	  if (!mqtt_ || mqtt_->HasConnectedOnce()) {
317	    return;  // 首连成功后由 automatic_reconnect 接管，无需人工重试
318	  }
319	  const std::string uri = "tcp://" + mqtt_broker_host_ + ":" + std::to_string(mqtt_port_);
320	  const std::string client_id = "amr_dispatcher_gateway_" + serial_number_;
321	  const std::vector<std::string> filters = {TopicBase() + "/+/+/state",
322	                                            TopicBase() + "/+/+/connection"};
323	  const std::string lwt_topic = MqttTopic(manufacturer_, serial_number_, "connection");
324	  const std::string lwt_payload = BuildGatewayConnectionJson("CONNECTIONBROKEN");
325	
326	  std::string err;
327	  const bool ok = mqtt_->Connect(
328	      uri, client_id, filters, kQosConnection, lwt_topic, lwt_payload, kQosConnection,
329	      [this](const std::string& topic, const std::string& payload) {
330	        OnMqttMessage(topic, payload);
331	      },
332	      &err);
333	  if (ok) {
334	    RCLCPP_INFO(get_logger(), "MQTT 已连接 %s (client_id=%s, base=%s, LWT=%s)", uri.c_str(),
335	                client_id.c_str(), TopicBase().c_str(), lwt_topic.c_str());
336	  } else {
337	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
338	                         "MQTT 连接失败 %s: %s（首连前每 5s 重试，首连成功后由自动重连接管）",
339	                         uri.c_str(), err.c_str());
340	  }
341	}
