343	void Vda5050GatewayNode::OnMqttMessage(const std::string& topic, std::string payload) {
344	  std::lock_guard<std::mutex> lock(inbound_mutex_);
345	  if (inbound_queue_.size() >= kMaxInboundQueue) {
346	    inbound_queue_.pop_front();
347	    dropped_messages_.fetch_add(1, std::memory_order_relaxed);
348	  }
349	  inbound_queue_.emplace_back(topic, std::move(payload));
350	}
351	
352	void Vda5050GatewayNode::DrainInboundQueue() {
353	  std::deque<std::pair<std::string, std::string>> batch;
354	  {
355	    std::lock_guard<std::mutex> lock(inbound_mutex_);
356	    batch.swap(inbound_queue_);
357	  }
358	  const std::size_t dropped = dropped_messages_.exchange(0, std::memory_order_relaxed);
359	  if (dropped > 0) {
360	    RCLCPP_WARN(get_logger(),
361	                "入站队列溢出，丢弃 %zu 条 MQTT 消息（可调低负载或提高出队频率 kDrainPeriodMs）",
362	                dropped);
363	  }
364	  for (const auto& item : batch) {
365	    const InboundTopic parsed = ParseInboundTopic(item.first);
366	    if (!parsed.valid) {
367	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000, "忽略无法解析的 MQTT Topic: %s",
368	                           item.first.c_str());
369	      continue;
370	    }
371	    // 网关自身 connection 心跳/LWT 不回环进 ROS 侧
372	    if (parsed.vehicle_id == serial_number_) {
373	      continue;
374	    }
375	    VehicleEndpoints& ep = EnsureVehicle(parsed.vehicle_id, parsed.manufacturer);
376	    if (parsed.leaf == "state") {
377	      HandleStateMessage(parsed.vehicle_id, item.second, ep);
378	    } else {
379	      HandleConnectionMessage(parsed.vehicle_id, item.second, ep);
380	    }
381	  }
382	}
