384	void Vda5050GatewayNode::HandleStateMessage(const std::string& vehicle_id,
385	                                            const std::string& payload, VehicleEndpoints& ep) {
386	  if (!ep.state_pub) {
387	    return;  // 非法 vehicle_id 已在 EnsureVehicle 告警，该车无 ROS 端点
388	  }
389	  const auto report = amr_dispatcher_core::fleet::DeserializeVda5050State(payload);
390	  if (!report.has_value()) {
391	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
392	                         "丢弃非法 VDA 5050 state 报文 (vehicle=%s)", vehicle_id.c_str());
393	    return;
394	  }
395	  // 无损透传原始 JSON，Task 5 调度侧可用 DeserializeVda5050State 按需解析
396	  std_msgs::msg::String raw;
397	  raw.data = payload;
398	  ep.state_pub->publish(raw);
399	
400	  geometry_msgs::msg::PoseStamped pose;
401	  pose.header.stamp = now();
402	  pose.header.frame_id = "map";
403	  pose.pose.position.x = report->x;
404	  pose.pose.position.y = report->y;
405	  pose.pose.orientation.z = std::sin(report->yaw * 0.5);
406	  pose.pose.orientation.w = std::cos(report->yaw * 0.5);
407	  ep.pose_pub->publish(pose);
408	
409	  if (!ep.online) {
410	    ep.online = true;
411	    std_msgs::msg::Bool online_msg;
412	    online_msg.data = true;
413	    ep.online_pub->publish(online_msg);
414	  }
415	}
416	
417	void Vda5050GatewayNode::HandleConnectionMessage(const std::string& vehicle_id,
418	                                                 const std::string& payload,
419	                                                 VehicleEndpoints& ep) {
420	  const auto connection = amr_dispatcher_core::fleet::DeserializeVda5050Connection(payload);
421	  if (!connection.has_value()) {
422	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
423	                         "丢弃非法 VDA 5050 connection 报文 (vehicle=%s)", vehicle_id.c_str());
424	    return;
425	  }
426	  if (*connection == "CONNECTIONBROKEN") {
427	    // 安全铁律（Spec §3 / §5.2）：网关绝不释放任何路权锁——
428	    // 仅将 /fleet/{vid}/online 置 false；锁保留与逐段释放由调度核心 (Task 5) 负责。
429	    RCLCPP_WARN(get_logger(),
430	                "车辆 %s MQTT 连接断开 (LWT CONNECTIONBROKEN)：仅发布 /fleet/%s/online=false，"
431	                "绝不释放该车持有的路权锁（锁保留归调度核心 Task 5）",
432	                vehicle_id.c_str(), vehicle_id.c_str());
433	  }
434	  if (!ep.online_pub) {
435	    return;  // 非法 vehicle_id 无 ROS 端点
436	  }
437	  const bool online = (*connection == "ONLINE");
438	  ep.online = online;
439	  std_msgs::msg::Bool online_msg;
440	  online_msg.data = online;
441	  ep.online_pub->publish(online_msg);
442	}
