444	void Vda5050GatewayNode::SendOrderCallback(const std::string& vehicle_id,
445	                                           const std::string& manufacturer,
446	                                           const std_msgs::msg::String::SharedPtr& msg) {
447	  const std::string payload = Trim(msg->data);
448	  if (payload.empty()) {
449	    RCLCPP_WARN(get_logger(), "send_order 收到空报文 (vehicle=%s)，忽略", vehicle_id.c_str());
450	    return;
451	  }
452	  if (payload.front() != '{') {
453	    RCLCPP_WARN(get_logger(),
454	                "send_order 期望 Vda5050OrderBuilder 序列化的 Order JSON，实际开头 '%c' (vehicle=%s)，忽略",
455	                payload.front(), vehicle_id.c_str());
456	    return;
457	  }
458	  const std::string topic = MqttTopic(manufacturer, vehicle_id, "order");
459	  std::string err;
460	  if (mqtt_ && mqtt_->Publish(topic, payload, kQosOrder, false, &err)) {
461	    RCLCPP_INFO(get_logger(), "Order 已下发 MQTT: %s (%zu bytes)", topic.c_str(), payload.size());
462	  } else {
463	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000, "Order 下发失败 (topic=%s): %s",
464	                         topic.c_str(),
465	                         (mqtt_ == nullptr) ? "MQTT 子系统未启用" : err.c_str());
466	  }
467	}
