469	void Vda5050GatewayNode::InstantActionsCallback(const std::string& vehicle_id,
470	                                                const std::string& manufacturer,
471	                                                const std_msgs::msg::String::SharedPtr& msg) {
472	  const std::string payload = Trim(msg->data);
473	  if (payload.empty()) {
474	    RCLCPP_WARN(get_logger(), "instant_actions 收到空报文 (vehicle=%s)，忽略", vehicle_id.c_str());
475	    return;
476	  }
477	
478	  std::string json;
479	  if (payload.front() == '{') {
480	    json = payload;  // 已是完整 VDA 5050 instantActions JSON，原样透传
481	  } else {
482	    const char* canonical = nullptr;
483	    for (const auto& alias : kInstantActionAliases) {
484	      if (payload == alias.alias) {
485	        canonical = alias.action_type;
486	        break;
487	      }
488	    }
489	    if (canonical == nullptr) {
490	      RCLCPP_WARN(get_logger(),
491	                  "instant_actions 不支持的简单指令 '%s' (vehicle=%s)，"
492	                  "支持: cancelOrder/pause/resume/stopPause，或完整 instantActions JSON",
493	                  payload.c_str(), vehicle_id.c_str());
494	      return;
495	    }
496	    amr_dispatcher_core::fleet::VehicleAction action;
497	    action.action_type = canonical;
498	    action.action_id = "ia_" + std::to_string(g_instant_action_seq.fetch_add(1));
499	    std::vector<amr_dispatcher_core::fleet::VehicleAction> actions{std::move(action)};
500	    json = amr_dispatcher_core::fleet::SerializeVda5050InstantActions(vehicle_id, actions,
501	                                                                     protocol_version_, manufacturer);
502	  }
503	
504	  const std::string topic = MqttTopic(manufacturer, vehicle_id, "instantActions");
505	  std::string err;
506	  if (mqtt_ && mqtt_->Publish(topic, json, kQosInstantActions, false, &err)) {
507	    RCLCPP_INFO(get_logger(), "InstantActions 已下发 MQTT: %s (%zu bytes)", topic.c_str(),
508	                json.size());
509	  } else {
510	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000, "InstantActions 下发失败 (topic=%s): %s",
511	                         topic.c_str(),
512	                         (mqtt_ == nullptr) ? "MQTT 子系统未启用" : err.c_str());
513	  }
514	}
