516	void Vda5050GatewayNode::PublishGatewayHeartbeat() {
517	  if (!mqtt_) return;
518	  const std::string topic = MqttTopic(manufacturer_, serial_number_, "connection");
519	  const std::string json = BuildGatewayConnectionJson("ONLINE");
520	  std::string err;
