527	Vda5050GatewayNode::VehicleEndpoints& Vda5050GatewayNode::EnsureVehicle(
528	    const std::string& vehicle_id, const std::string& manufacturer) {
529	  auto it = vehicles_.find(vehicle_id);
530	  if (it != vehicles_.end()) {
531	    return it->second;
532	  }
533	  VehicleEndpoints ep;
534	  ep.manufacturer = manufacturer;  // manufacturer 以首见为准，保证后续原路回发
535	  if (!IsValidVehicleId(vehicle_id)) {
536	    RCLCPP_ERROR(get_logger(),
537	                 "serialNumber '%s' 不是合法 ROS 话题段（须字母或 '_' 开头，仅含字母/数字/'_'），"
538	                 "跳过该车全部 ROS 端点创建（MQTT 订阅解析不受影响）",
539	                 vehicle_id.c_str());
540	  } else {
541	    try {
542	      const std::string base = "/fleet/" + vehicle_id;
543	      ep.state_pub = create_publisher<std_msgs::msg::String>(base + "/state", 10);
544	      ep.pose_pub = create_publisher<geometry_msgs::msg::PoseStamped>(base + "/pose", 10);
545	      ep.online_pub = create_publisher<std_msgs::msg::Bool>(
546	          base + "/online", rclcpp::QoS(rclcpp::KeepLast(1)).transient_local());
547	      ep.send_order_sub = create_subscription<std_msgs::msg::String>(
548	          base + "/send_order", 10,
549	          [this, vehicle_id, manufacturer](const std_msgs::msg::String::SharedPtr m) {
550	            SendOrderCallback(vehicle_id, manufacturer, m);
551	          });
552	      ep.instant_actions_sub = create_subscription<std_msgs::msg::String>(
553	          base + "/instant_actions", 10,
554	          [this, vehicle_id, manufacturer](const std_msgs::msg::String::SharedPtr m) {
555	            InstantActionsCallback(vehicle_id, manufacturer, m);
556	          });
557	      RCLCPP_INFO(get_logger(),
558	                  "发现车辆 %s (manufacturer=%s)，已创建 ROS 端点 %s/{state,pose,online,send_order,instant_actions}",
559	                  vehicle_id.c_str(), manufacturer.c_str(), base.c_str());
560	    } catch (const std::exception& e) {
561	      RCLCPP_ERROR(get_logger(), "创建车辆 %s 的 ROS 端点失败: %s", vehicle_id.c_str(), e.what());
562	      ep = VehicleEndpoints{};  // 部分创建失败则整体放弃，避免半残端点
563	      ep.manufacturer = manufacturer;
564	    }
565	  }
566	  return vehicles_.emplace(vehicle_id, std::move(ep)).first->second;
567	}
