569	Vda5050GatewayNode::InboundTopic Vda5050GatewayNode::ParseInboundTopic(const std::string& topic) {
570	  InboundTopic out;
571	  std::vector<std::string> parts;
572	  std::size_t start = 0;
573	  while (start <= topic.size()) {
574	    const std::size_t pos = topic.find('/', start);
575	    if (pos == std::string::npos) {
576	      parts.push_back(topic.substr(start));
577	      break;
578	    }
579	    parts.push_back(topic.substr(start, pos - start));
580	    start = pos + 1;
581	  }
582	  if (parts.size() != 5) {
583	    return out;  // base/manufacturer/serial/leaf 才是 4 段；此处 topic 含首段，共 5
584	  }
585	  if (parts[4] != "state" && parts[4] != "connection") {
586	    return out;
587	  }
588	  if (parts[2].empty() || parts[3].empty()) {
589	    return out;
590	  }
591	  out.valid = true;
592	  out.manufacturer = parts[2];
593	  out.vehicle_id = parts[3];
594	  out.leaf = parts[4];
595	  return out;
596	}
