598	bool Vda5050GatewayNode::IsValidVehicleId(const std::string& vehicle_id) {
599	  if (vehicle_id.empty()) return false;
600	  const auto ok_first = [](char c) {
601	    return std::isalpha(static_cast<unsigned char>(c)) != 0 || c == '_';
602	  };
603	  if (!ok_first(vehicle_id[0])) return false;
604	  for (const char c : vehicle_id) {
605	    if (std::isalnum(static_cast<unsigned char>(c)) == 0 && c != '_') return false;
606	  }
607	  return true;
608	}
