619	
620	std::string Vda5050GatewayNode::BuildGatewayConnectionJson(const std::string& state) const {
621	  const std::string vda_version = (protocol_version_ == "v3") ? "3.0.0" : "2.0.0";
622	  std::ostringstream ss;
